from typing import List
from collections import defaultdict

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        NEG_INF = float('-inf')
        EMPTY = (0, NEG_INF, NEG_INF, NEG_INF)

        def combine(a, b):
            at, ap, asu, ab = a
            bt, bp, bsu, bb = b
            return (at + bt,
                    max(ap, at + bp),
                    max(bsu, bt + asu),
                    max(ab, bb, asu + bp))

        size = 1
        while size < n:
            size *= 2
        if size == 0:
            size = 1
        tree = [EMPTY] * (2 * size)
        for i in range(n):
            v = nums[i]
            tree[size + i] = (v, v, v, v)
        for i in range(size - 1, 0, -1):
            tree[i] = combine(tree[2 * i], tree[2 * i + 1])

        def query(l, r):
            if l > r:
                return EMPTY
            res_l = EMPTY
            res_r = EMPTY
            l += size
            r += size + 1
            while l < r:
                if l & 1:
                    res_l = combine(res_l, tree[l])
                    l += 1
                if r & 1:
                    r -= 1
                    res_r = combine(tree[r], res_r)
                l //= 2
                r //= 2
            return combine(res_l, res_r)

        ans = query(0, n - 1)[3]

        positions = defaultdict(list)
        for i, v in enumerate(nums):
            positions[v].append(i)

        for v, pos in positions.items():
            if v >= 0:
                continue
            if len(pos) == n:
                continue
            combined = EMPTY
            prev = -1
            for p in pos:
                if prev + 1 <= p - 1:
